class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance
        self.history = []

    def deposit(self, amount):
        self.balance += amount
        self.history.append(f'+{amount}')

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError('余额不足，义体银行拒绝该操作')
        self.balance -= amount
        self.history.append(f'-{amount}')

acc = BankAccount('V', 100)
acc.deposit(50)
acc.withdraw(30)
