import time
def timer(fn):
    def wrapper(*args):
        t0 = time.time()
        result = fn(*args)
        print(f'{fn.__name__} 耗时 {time.time()-t0:.4f}s')
        return result
    return wrapper

@timer
def wait():
    time.sleep(0.1)

wait()

def log_call(fn):
    def wrapper(*args):
        print(f'调用 {fn.__name__}{args}')
        result = fn(*args)
        print(f'返回 {result}')
        return result
    return wrapper

@log_call
def add(a, b):
    return a + b

add(3, 5)

